import React, { useState, useEffect } from 'react';
import { goalsAPI } from '../utils/api';
import { Plus, Edit, Trash2, Target } from 'lucide-react';
import toast from 'react-hot-toast';

const Goals = () => {
  const [goals, setGoals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingGoal, setEditingGoal] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    deadline: '',
    progress: 0,
    type: 'short-term'
  });

  useEffect(() => {
    fetchGoals();
  }, []);

  const fetchGoals = async () => {
    try {
      const response = await goalsAPI.getAll();
      setGoals(response.data);
    } catch (error) {
      // Demo mode - use local storage
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      setGoals(savedGoals);
      console.log('Using demo mode - goals stored locally');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingGoal) {
        await goalsAPI.update(editingGoal._id, formData);
        toast.success('Goal updated successfully');
      } else {
        await goalsAPI.create(formData);
        toast.success('Goal created successfully');
      }
      setShowModal(false);
      setEditingGoal(null);
      setFormData({ title: '', description: '', deadline: '', progress: 0, type: 'short-term' });
      fetchGoals();
    } catch (error) {
      // Demo mode - save to local storage
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      const newGoal = {
        _id: Date.now().toString(),
        ...formData,
        completed: false,
        createdAt: new Date().toISOString()
      };

      if (editingGoal) {
        const updatedGoals = savedGoals.map(goal => 
          goal._id === editingGoal._id ? { ...goal, ...formData } : goal
        );
        localStorage.setItem('goals', JSON.stringify(updatedGoals));
        toast.success('Goal updated successfully (Demo Mode)');
      } else {
        savedGoals.push(newGoal);
        localStorage.setItem('goals', JSON.stringify(savedGoals));
        toast.success('Goal created successfully (Demo Mode)');
      }

      setShowModal(false);
      setEditingGoal(null);
      setFormData({ title: '', description: '', deadline: '', progress: 0, type: 'short-term' });
      fetchGoals();
    }
  };

  const handleEdit = (goal) => {
    setEditingGoal(goal);
    setFormData({
      title: goal.title,
      description: goal.description,
      deadline: goal.deadline.split('T')[0],
      progress: goal.progress,
      type: goal.type || 'short-term'
    });
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this goal?')) {
      try {
        await goalsAPI.delete(id);
        toast.success('Goal deleted successfully');
        fetchGoals();
      } catch (error) {
        // Demo mode - delete from local storage
        const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
        const updatedGoals = savedGoals.filter(goal => goal._id !== id);
        localStorage.setItem('goals', JSON.stringify(updatedGoals));
        toast.success('Goal deleted successfully (Demo Mode)');
        fetchGoals();
      }
    }
  };

  const handleProgressUpdate = async (id, progress) => {
    try {
      const completed = progress >= 100;
      await goalsAPI.update(id, { progress, completed });
      toast.success('Progress updated');
      fetchGoals();
    } catch (error) {
      // Demo mode - update in local storage
      const savedGoals = JSON.parse(localStorage.getItem('goals') || '[]');
      const updatedGoals = savedGoals.map(goal => 
        goal._id === id ? { ...goal, progress, completed: progress >= 100 } : goal
      );
      localStorage.setItem('goals', JSON.stringify(updatedGoals));
      toast.success('Progress updated (Demo Mode)');
      fetchGoals();
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-indigo-50 to-purple-50 ml-64 pt-16">
      <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold text-gray-800 mb-4">
            Goal
            <span className="bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent"> Achievement</span>
          </h1>
          <p className="text-xl text-gray-600 mb-8">
            Set, track, and achieve your short-term and long-term goals
          </p>
          <button
            onClick={() => setShowModal(true)}
            className="inline-flex items-center px-8 py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl text-lg font-semibold hover:from-blue-700 hover:to-purple-700 transition-all duration-300 shadow-lg hover:shadow-xl transform hover:scale-105"
          >
            <Plus className="w-5 h-5 mr-2" />
            Add New Goal
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {goals.length > 0 ? (
            goals.map((goal) => (
              <div key={goal._id} className="group bg-white rounded-3xl border-2 border-gray-100 hover:border-gray-200 p-8 shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-2 overflow-hidden relative">
                {/* Background decoration */}
                <div className={`absolute top-0 right-0 w-20 h-20 rounded-full opacity-10 -translate-y-10 translate-x-10 ${
                  goal.type === 'long-term' ? 'bg-gradient-to-br from-purple-400 to-pink-400' : 'bg-gradient-to-br from-blue-400 to-indigo-400'
                }`}></div>

                <div className="flex items-start justify-between mb-6 relative z-10">
                  <div className="flex items-center">
                    <div className={`p-3 rounded-2xl mr-4 group-hover:scale-110 transition-transform duration-300 ${
                      goal.type === 'long-term' ? 'bg-purple-50 text-purple-600' : 'bg-blue-50 text-blue-600'
                    }`}>
                      <Target className="w-6 h-6" />
                    </div>
                    <div>
                      <h3 className="text-xl font-bold text-gray-900 group-hover:text-blue-600 transition-colors">{goal.title}</h3>
                      <span className={`inline-block px-3 py-1 rounded-full text-xs font-semibold mt-2 ${
                        goal.type === 'long-term' ? 'bg-purple-100 text-purple-800' : 'bg-blue-100 text-blue-800'
                      }`}>
                        {goal.type === 'long-term' ? '🎯 Long Term' : '⚡ Short Term'}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    <button
                      onClick={() => handleEdit(goal)}
                      className="p-3 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all duration-200"
                    >
                      <Edit className="w-5 h-5" />
                    </button>
                    <button
                      onClick={() => handleDelete(goal._id)}
                      className="p-3 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all duration-200"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </div>
                </div>

                {goal.description && (
                  <p className="text-gray-600 mb-6 text-lg leading-relaxed">{goal.description}</p>
                )}

                <div className="mb-6">
                  <div className="flex justify-between items-center mb-3">
                    <span className="text-lg font-semibold text-gray-800">Progress</span>
                    <span className={`text-2xl font-bold ${
                      goal.progress >= 100 ? 'text-green-600' : goal.progress >= 50 ? 'text-blue-600' : 'text-gray-600'
                    }`}>{goal.progress}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-4 mb-4">
                    <div
                      className={`h-4 rounded-full transition-all duration-500 ${
                        goal.progress >= 100 ? 'bg-gradient-to-r from-green-400 to-green-600' :
                        goal.progress >= 50 ? 'bg-gradient-to-r from-blue-400 to-blue-600' :
                        'bg-gradient-to-r from-gray-400 to-gray-500'
                      }`}
                      style={{ width: `${goal.progress}%` }}
                    ></div>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={goal.progress}
                    onChange={(e) => handleProgressUpdate(goal._id, parseInt(e.target.value))}
                    className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer slider"
                  />
                </div>

                <div className="flex justify-between items-center">
                  <span className="text-gray-500 font-medium">
                    📅 {new Date(goal.deadline).toLocaleDateString()}
                  </span>
                  {goal.completed && (
                    <span className="px-4 py-2 bg-gradient-to-r from-green-400 to-green-600 text-white rounded-full text-sm font-bold shadow-lg">
                      ✅ Completed!
                    </span>
                  )}
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full text-center py-20">
              <div className="w-24 h-24 bg-gradient-to-r from-blue-100 to-purple-100 rounded-full flex items-center justify-center mx-auto mb-6">
                <Target className="w-12 h-12 text-blue-600" />
              </div>
              <h3 className="text-2xl font-bold text-gray-800 mb-4">No goals yet!</h3>
              <p className="text-gray-600 text-lg">Set your first goal and start your achievement journey.</p>
            </div>
          )}
        </div>

        {/* Modal */}
        {showModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white dark:bg-gray-800 rounded-lg max-w-md w-full p-6">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                {editingGoal ? 'Edit Goal' : 'Add New Goal'}
              </h2>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Title
                  </label>
                  <input
                    type="text"
                    required
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Description
                  </label>
                  <textarea
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    rows="3"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Goal Type
                  </label>
                  <select
                    value={formData.type}
                    onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  >
                    <option value="short-term">Short Term Goal</option>
                    <option value="long-term">Long Term Goal</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Deadline
                  </label>
                  <input
                    type="date"
                    required
                    value={formData.deadline}
                    onChange={(e) => setFormData({ ...formData, deadline: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
                <div className="flex justify-end space-x-3 pt-4">
                  <button
                    type="button"
                    onClick={() => {
                      setShowModal(false);
                      setEditingGoal(null);
                      setFormData({ title: '', description: '', deadline: '', progress: 0, type: 'short-term' });
                    }}
                    className="px-4 py-2 text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-4 py-2 bg-primary-600 text-white rounded-md hover:bg-primary-700"
                  >
                    {editingGoal ? 'Update' : 'Create'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Goals;
